import json, subprocess, warnings, os
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "बुखार जो जा नहीं रहा? जोड़ों में दर्द और अकड़न? और डॉक्टर ने लिख दिया, ई एस आर और सी आर पी? आज रविवार की हेल्थ टिप में जानिए, ये दोनों टेस्ट क्या बताते हैं. आखिर तक देखिए.",
 "जब शरीर में इंफेक्शन, चोट, या किसी बीमारी से सूजन होती है, तो उसे इन्फ्लेमेशन कहते हैं. ई एस आर और सी आर पी, स्मोक अलार्म की तरह हैं. ये बताते हैं कि शरीर में कहीं इन्फ्लेमेशन है. पर यह नहीं बताते, कि कहाँ है, और क्यों है.",
 "ई एस आर का मतलब है, एरिथ्रोसाइट सेडिमेंटेशन रेट. खून को एक लंबी पतली ट्यूब में खड़ा रखा जाता है. एक घंटे में लाल रक्त कोशिकाएं कितने मिलीमीटर नीचे बैठीं, वही ई एस आर है. इन्फ्लेमेशन हो, तो ये कोशिकाएं आमतौर पर तेज़ी से नीचे बैठती हैं, और ई एस आर बढ़ जाता है.",
 "सी आर पी, यानी सी रिएक्टिव प्रोटीन, लिवर बनाता है. इन्फ्लेमेशन शुरू होने के कुछ ही घंटों में यह बढ़ने लगता है, और ठीक होने पर जल्दी कम भी हो जाता है. ई एस आर धीमा है. यह एक दो दिन में बढ़ता है, और नॉर्मल होने में कई हफ्ते लग सकते हैं.",
 "डॉक्टर ये टेस्ट कब करवाते हैं? बिना वजह का लंबा बुखार. जोड़ों में दर्द, सूजन या अकड़न. मांसपेशियों में दर्द. किसी इंफेक्शन का शक. और गठिया जैसी बीमारियों में, इलाज का असर देखने के लिए भी.",
 "यह एक साधारण ब्लड टेस्ट है. आमतौर पर खाली पेट की ज़रूरत नहीं होती, फिर भी अपनी लैब का निर्देश मानें. जो दवाएं ले रहे हैं, डॉक्टर को बताएं. एक खास टेस्ट है, एच एस सी आर पी. यह बहुत कम सी आर पी भी पकड़ लेता है, और कभी कभी दिल की बीमारी का खतरा आंकने में मदद करता है.",
 "रिपोर्ट कैसे पढ़ें? ई एस आर लगभग, पचास साल से कम उम्र के पुरुषों में पंद्रह तक, और महिलाओं में बीस तक. पचास के बाद यह थोड़ा ज़्यादा हो सकता है. सी आर पी ज़्यादातर स्वस्थ लोगों में बहुत कम होता है. ध्यान दें, कुछ लैब इसे एम जी पर लीटर में, और कुछ एम जी पर डी एल में लिखती हैं. इसलिए अपनी रिपोर्ट पर लिखी रेंज ही देखें.",
 "कुछ ज़रूरी बातें. उम्र, महिलाओं में, प्रेग्नेंसी, और खून की कमी में, ई एस आर थोड़ा ज़्यादा आ सकता है. मोटापा और धूम्रपान से सी आर पी हल्का बढ़ सकता है. मिथक, ई एस आर ज़्यादा है, तो ज़रूर टी बी या कैंसर है. सच, इसके कई आम कारण होते हैं. वजह जानने के लिए डॉक्टर लक्षण और दूसरे टेस्ट के साथ देखते हैं. और नॉर्मल रिपोर्ट भी हर बीमारी को पूरी तरह रूल आउट नहीं करती.",
 close_voice("क्या आपने कभी ई एस आर या सी आर पी टेस्ट करवाया है?"),
]
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/escr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/esc_{i}.wav"],check=True); f=f"/tmp/esc_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/esc_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
